```typescript
import { invoke } from "@tauri-apps/api/core";
import { useState } from "react";
import "./App.css";
import reactLogo from "./assets/react.svg";

function App() {
  const [greetMsg, setGreetMsg] = useState("");
  const [name, setName] = useState("");

  async function handleGreetAll() {
    const [salute, fromMe, fromYou] = await Promise.all([
      invoke<string>("salute", { name }),
      invoke<string>("greet_from_me", { name }),
      invoke<string>("greet_from_you", { name }),
    ]);
    setGreetMsg([salute, fromMe, fromYou].join("\n"));
  }

  return (
    <main className="container">
      <h1>Welcome to Tauri + React</h1>

      <div className="row">
        <a href="https://vite.dev" target="_blank">
          <img src="/vite.svg" className="logo vite" alt="Vite logo" />
        </a>
        <a href="https://tauri.app" target="_blank">
          <img src="/tauri.svg" className="logo tauri" alt="Tauri logo" />
        </a>
        <a href="https://react.dev" target="_blank">
          <img src={reactLogo} className="logo react" alt="React logo" />
        </a>
      </div>
      <p>Click on the Tauri, Vite, and React logos to learn more.</p>

      <form
        className="row"
        onSubmit={(e) => {
          e.preventDefault();
          handleGreetAll();
        }}
      >
        <input
          id="greet-input"
          onChange={(e) => setName(e.currentTarget.value)}
          placeholder="Enter a name..."
        />
        <button type="submit">Greet</button>
      </form>
      <pre>{greetMsg}</pre>
    </main>
  );
}

export default App;
```

The `_getMethodNames()` method walks the prototype chain to collect method names for plugin application, but lacked safeguards against pathological cases.

## Changes

- **Maximum depth limit**: Added `MAX_DEPTH = 50` constant to prevent infinite loops in degenerate prototype chains
- **Cycle detection**: Track visited prototypes in a `Set<object>` to detect and break on circular references
- Both checks exit early if triggered, before any issues manifest

```typescript
private _getMethodNames(): string[] {
  const methods: string[] = [];
  const proto = Object.getPrototypeOf(this);

  // Walk up the prototype chain with safety checks
  const MAX_DEPTH = 50;
  const visited = new Set<object>();

  let current = proto;
  let depth = 0;

  while (current && current !== Object.prototype) {
    if (depth >= MAX_DEPTH || visited.has(current)) {
      break;
    }
    visited.add(current);

    // ... collect method names

    current = Object.getPrototypeOf(current);
    depth++;
  }

  return methods;
}
```

These safeguards are unlikely to trigger in normal operation but provide robustness against edge cases in dynamically constructed prototype chains.

